def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n == 2:
        if history[0][1] == 'D' and history[1][1] == 'D':
            return 'D'
        if history[1][1] == 'D':
            return 'D'
        return 'C'

    opp = [b for a, b in history]
    me = [a for a, b in history]
    opp_c = sum(1 for x in opp if x == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for x in me if x == 'D')
    last_me = me[-1]
    last_opp = opp[-1]

    recent = opp[-6:] if n >= 6 else opp
    recent_d = sum(1 for x in recent if x == 'D')
    recent_c = len(recent) - recent_d

    # Punish a strongly defecting opponent.
    if n >= 8 and opp_d * 3 >= n * 2:
        return 'D'

    # Last few rounds: exploit mostly-cooperative partners.
    if n >= 88:
        if opp_c * 10 >= n * 7:
            return 'D'
        if opp_d * 10 >= n * 7:
            return 'D'
        return 'C'

    # If opponent defected last but has been mostly cooperative recently, forgive.
    if last_opp == 'D':
        if recent_d <= 1 and opp_d * 4 <= n:
            return 'C'
        if last_me == 'D' and recent_c >= 1:
            return 'C'
        if my_d * 2 > n and opp_d > 2:
            return 'C' if rng.random() < 0.4 else 'D'
        return 'D'

    # Opponent cooperated last.
    if last_me == 'D':
        return 'C'
    if recent_d >= 3:
        return 'D'
    # Occasionally probe otherwise very cooperative partners.
    if n >= 30 and opp_d == 0 and my_d * 2 < n:
        if rng.random() < 0.12:
            return 'D'
    return 'C'
